function byLeafId(a, b) {
  const l = a.split('.').map(Number);
  const r = b.split('.').map(Number);
  for (let i = 0; i < Math.max(l.length, r.length); i += 1) {
    if ((l[i] ?? 0) !== (r[i] ?? 0)) return (l[i] ?? 0) - (r[i] ?? 0);
  }
  return 0;
