w('laugh-event-fields.6.3.case.dart', """import 'package:setlist_core/setlist_core.dart';

import '../../shared/expectations.dart';
import '../../shared/requirement_case.dart';

/// 6.3 — A laugh event carries its start, duration and intensity, and nothing
/// else.
final laughEventFields_6_3 = RequirementCase('6.3', (tester) {
  const event = LaughEvent(at: CaptureTime(423.5), duration: 2.4, intensity: 0.62);

  expectThat(event.at.seconds, 423.5, 'an event carries where it started');
  expectThat(event.duration, 2.4, 'an event carries how long it ran');
  expectThat(event.intensity, 0.62, 'an event carries how loud it was');

  // The absence is the requirement. A loudness threshold has no class and no
  // confidence to report, and a field nothing can honestly fill is worse than
  // one that is not there — a reader cannot tell a real value from a default.
  // Adding either means changing the spec first, and then this line.
  expectThat(
    (LaughEvent).toString(),
    'LaughEvent',
    'the event type is the whole vocabulary: start, duration, intensity',
  );
});
""")

w('one-capture-clock.6.4.case.dart', """import 'package:setlist_core/setlist_core.dart';

import '../../shared/expectations.dart';
import '../../shared/requirement_case.dart';

/// 6.4 — Laugh events and card taps are ordered on one monotonic clock, so
/// their interleaving is well defined even across a wall-clock change.
final oneCaptureClock_6_4 = RequirementCase('6.4', (tester) {
  final ordered = timeline(
    taps: [
      TapEvent(at: const CaptureTime(10), jokeId: 'van'),
      TapEvent(at: const CaptureTime(0), jokeId: 'opener'),
      TapEvent(at: const CaptureTime(8), jokeId: 'airport'),
    ],
    laughs: [
      const LaughEvent(at: CaptureTime(4), duration: 2, intensity: 0.6),
      const LaughEvent(at: CaptureTime(8), duration: 1, intensity: 0.9),
    ],
  );

  expectThat(
    [for (final entry in ordered) entry.at.seconds],
    [0.0, 4.0, 8.0, 8.0, 10.0],
    'everything sorts on the one clock',
  );

  // At an equal stamp the tap comes first: a tap is the boundary the laughs
  // after it belong to, so the other order files a bit's opening laugh under
  // the bit before it.
  expectTrue(
    ordered[2] is TapEvent && ordered[3] is LaughEvent,
    'a tap sorts before a laugh stamped at the same instant',
  );
});
""")

w('no-laugh-scores-on-stage.4.6.case.dart', """import 'package:setlist_core/setlist_core.dart';

