  final container = await Directory.systemTemp.createTemp('setlist-relaunch');
  try {
    await FileLibraryStore.inContainer(container).save(
      Library(
        jokes: [
          Joke(
            id: 'airport',
            title: 'Airport security',
            body: 'Shoes off.',
            estimatedLength: const Duration(seconds: 145),
