  _run('behavior', behaviorCases);
  _run('screen', screenCases);
  _run('saga', sagaCases);
}

void _run(String kind, List<RequirementCase> cases) {
  group(kind, () {
    for (final requirement in cases) {
      testWidgets(requirement.id, requirement.verify);
    }
  });
}
